package com.microapp.autumn.api.extension;

import com.microapp.autumn.api.config.ServiceConfig;

/**
 * compile-time generated service assembler, generated by autumn-compiler for each @Export class.
 *
 * <pre>
 *     instead of runtime reflection, autumn-compiler(JSR-269) generates a
 *     <code>_XxxServiceRegister</code> class which implements this interface,
 *     so that provider can be exported with zero reflection (native image friendly).
 * </pre>
 *
 * @author: baoxin.zhao
 * @date: 2026/11/3
 */
public interface AutumnServiceAssembler {

    /**
     * whether this assembler supports the given implementation class
     *
     * @param implClass implementation class annotated with @Export
     * @return true if supported
     */
    boolean supports(Class<?> implClass);

    /**
     * build ServiceConfig for the given implementation instance
     *
     * @param impl implementation instance
     * @return ServiceConfig ready for AutumnBootstrap.service(config)
     */
    ServiceConfig<?> build(Object impl);
}
